//! Native expanded-name attribute presence uses actual Element storage.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn attribute_namespace_presence_canonical_method_and_genuine_receiver(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var m=Element.prototype.hasAttributeNS,desc=Object.getOwnPropertyDescriptor(Element.prototype,'hasAttributeNS'),n=document.getElementById('target');if(typeof m!=='function'||m.name!=='hasAttributeNS'||m.length!==2||Object.hasOwn(m,'prototype')||desc.value!==m||!desc.writable||!desc.enumerable||!desc.configurable||Object.hasOwn(n,'hasAttributeNS'))throw 'native canonical metadata';var calls=0,arg={toString:function(){calls++;throw 'must not convert';}};for(var x of [{},Object.create(Element.prototype),document,null,undefined]){var error;try{m.call(x,arg,arg);}catch(e){error=e;}if(!(error instanceof TypeError)||calls)throw 'brand before conversion';}if(m.call(n,null,'absent')!==false)throw 'recovery';"#);}

#[test]
fn attribute_namespace_presence_exact_namespace_local_name_and_live_prefix(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target');n.setAttributeNS(null,'data-test','');n.setAttributeNS('urn:a','p:Case','old');if(!n.hasAttributeNS(null,'data-test')||!n.hasAttributeNS('','data-test')||!n.hasAttributeNS(undefined,'data-test')||!n.hasAttributeNS('urn:a','Case')||n.hasAttributeNS('urn:a','case')||n.hasAttributeNS('urn:a','p:Case')||n.hasAttributeNS('urn:b','Case'))throw 'exact expanded name';n.setAttributeNS('urn:a','q:Case','new');if(!n.hasAttributeNS('urn:a','Case')||n.hasAttributeNS('urn:a','q:Case')||n.attributes.length!==3)throw 'prefix change retains expanded name';n.removeAttributeNS('urn:a','Case');if(n.hasAttributeNS('urn:a','Case'))throw 'live removal';"#);}

#[test]
fn attribute_namespace_presence_raw_namespace_and_local_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target');n.setAttributeNS('u\ud800','p:x\udfff','raw');n.setAttributeNS('u\ufffd','p:x\ufffd','scalar');if(!n.hasAttributeNS('u\ud800','x\udfff')||!n.hasAttributeNS('u\ufffd','x\ufffd')||n.hasAttributeNS('u\ud800','x\ufffd')||n.hasAttributeNS('u\ufffd','x\udfff'))throw 'exact raw expanded-name identity';n.setAttributeNS(null,'a\ud800','null raw');if(!n.hasAttributeNS(null,'a\ud800')||n.hasAttributeNS(null,'a\ufffd'))throw 'raw null namespace';"#);}

#[test]
fn attribute_namespace_presence_main_svg_inert_html_and_xml_owners(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var inert=document.implementation.createHTMLDocument('inert'),xml=new Document();for(var n of [document.getElementById('target'),document.getElementById('svg'),inert.createElement('p'),inert.createElementNS('http://www.w3.org/2000/svg','svg'),xml.createElement('item')]){n.setAttributeNS(null,'data-value','');if(!n.hasAttributeNS(null,'data-value')||n.hasAttributeNS('urn:a','absent'))throw 'genuine owner backing';if(n.namespaceURI!=='http://www.w3.org/2000/svg'){n.setAttributeNS('urn:a','p:local','value');if(!n.hasAttributeNS('urn:a','local'))throw 'owner namespace presence';n.removeAttributeNS('urn:a','local');if(n.hasAttributeNS('urn:a','local'))throw 'owner live removal';}}"#);}

#[test]
fn attribute_namespace_presence_argument_order_nullable_binding_and_abrupt_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),order='',ns={toString:function(){order+='n';return 'urn:a';}},local={toString:function(){order+='l';return 'x';}};n.setAttributeNS('urn:a','p:x','value');if(!n.hasAttributeNS(ns,local)||order!=='nl')throw 'ordered once binding';var error,calls=0,arg={toString:function(){calls++;return 'urn:a';}};try{n.hasAttributeNS(arg);}catch(e){error=e;}if(!(error instanceof TypeError)||calls)throw 'required args before conversion';var thrown={},seen=false;try{n.hasAttributeNS({toString:function(){throw thrown;}},local);}catch(e){seen=e===thrown;}if(!seen||order!=='nl')throw 'abrupt namespace identity';error=undefined;try{n.hasAttributeNS(Symbol('ns'),'x');}catch(e){error=e;}if(!(error instanceof TypeError)||!n.hasAttributeNS('urn:a','x'))throw 'symbol refusal and recovery';"#);}

#[test]
fn attribute_namespace_presence_saved_method_author_shadow_and_child_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),m=Element.prototype.hasAttributeNS;n.setAttributeNS(null,'data-test','v');n.hasAttributeNS=function(){throw 'author shadow';};if(!m.call(n,null,'data-test'))throw 'saved native method';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow.Element.prototype.hasAttributeNS;if(child===m||child.length!==2||!child.call(n,null,'data-test'))throw 'captured child native roots';var error;try{child.call({},null,'data-test');}catch(e){error=e;}if(!(error instanceof frame.contentWindow.TypeError))throw 'captured child brand realm';"#);}

#[test]
fn attribute_namespace_presence_borrowed_lookup_work_refusal_and_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target');n.setAttributeNS('urn:a','p:x','old');var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();p.state.copy_work=0;p.runtime.execute(r#"if(!n.hasAttributeNS('urn:a','x')||n.hasAttributeNS('urn:a','absent'))throw 'borrowed presence';"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();p.begin_job();p.state.host_work=0;assert!(p.runtime.execute(r#"n.hasAttributeNS('urn:a','x');"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);run(&mut d,&mut f,&mut p,r#"if(!n.hasAttributeNS('urn:a','x')||watch.takeRecords().length||n.getAttributeNS('urn:a','x')!=='old')throw 'refusal recovery';"#);}
